```c
#include <immintrin.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256])
{
    uint64_t t[4][256];
    memset(t, 0, sizeof(t));
    size_t i = 0;
    for (; i + 64 <= n; i += 64) {
        const uint8_t *p = data + i;
        uint64_t w[8];
        memcpy(w, p, 64);
        uint64_t pat = (uint64_t)p[0] * 0x0101010101010101ULL;
        uint64_t acc = (w[0] ^ pat) | (w[1] ^ pat) | (w[2] ^ pat) | (w[3] ^ pat) |
                       (w[4] ^ pat) | (w[5] ^ pat) | (w[6] ^ pat) | (w[7] ^ pat);
        if (acc == 0) {
            t[0][p[0]] += 64;
        } else {
            for (int j = 0; j < 64; j += 4) {
                t[0][p[j]]++;
                t[1][p[j + 1]]++;
                t[2][p[j + 2]]++;
                t[3][p[j + 3]]++;
            }
        }
    }
    for (; i < n; i++)
        t[0][data[i]]++;
    for (int b = 0; b < 256; b++)
        counts[b] = t[0][b] + t[1][b] + t[2][b] + t[3][b];
}
```
