#include <immintrin.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256]) {
    uint64_t t[4][256];
    memset(t, 0, sizeof t);
    memset(counts, 0, 256 * sizeof(uint64_t));
    size_t i = 0;
    unsigned runb = data && n ? data[0] : 0;
    uint64_t runlen = 0;
    for (; i + 64 <= n; i += 64) {
        const uint8_t *p = data + i;
        unsigned b = p[0];
        uint64_t pat = (uint64_t)b * 0x0101010101010101ULL;
        uint64_t w[8];
        memcpy(w, p, 64);
        uint64_t x = (w[0] ^ pat) | (w[1] ^ pat) | (w[2] ^ pat) | (w[3] ^ pat) |
                     (w[4] ^ pat) | (w[5] ^ pat) | (w[6] ^ pat) | (w[7] ^ pat);
        if (__builtin_expect(x == 0, 1)) {
            if (b == runb) {
                runlen += 64;
            } else {
                counts[runb] += runlen;
                runb = b;
                runlen = 64;
            }
        } else {
            for (int j = 0; j < 64; j += 4) {
                t[0][p[j]]++;
                t[1][p[j + 1]]++;
                t[2][p[j + 2]]++;
                t[3][p[j + 3]]++;
            }
        }
    }
    counts[runb] += runlen;
    for (; i < n; i++) counts[data[i]]++;
    for (int k = 0; k < 256; k++)
        counts[k] += t[0][k] + t[1][k] + t[2][k] + t[3][k];
}
```
