#ifdef __AVX2__
    while (i < n && (((uintptr_t)(out + i)) & 31)) {
        acc += in[i];
        out[i] = acc;
        i++;
    }
    if (n - i >= 8) {
        const __m256i zero = _mm256_setzero_si256();
        __m256i carry = _mm256_set1_epi64x(acc);
        for (; i + 8 <= n; i += 8) {
            __m256i a = _mm256_loadu_si256((const __m256i *)(in + i));
            __m256i b = _mm256_loadu_si256((const __m256i *)(in + i + 4));
