This is memory-bound: 128 MB in and 128 MB out, with sums up to about 1.6e13, so the output needs full 64-bit values. I wrote it in AVX2 intrinsics without compiling or running it, so the speedup is reasoned rather than measured. The approach:

- **Alignment head:** scalar code handles up to 3 elements until `out` is 32-byte aligned.
- **In-register prefix:** each 4×int64 vector is scanned with a lane shift-and-add, then a broadcast of element 1 added into the upper half.
- **Carry chain:** the carry is a broadcast vector updated with a single add per vector, so the dependency chain stays 1 cycle long. It is updated with the broadcast of the vector's local total (its last element), not of the carried sum.
- **Stores:** non-temporal aligned stores avoid the read-for-ownership on the output, cutting memory traffic by about a third. An `sfence` follows the loop.
- **Tail:** the leftover elements are summed in scalar code, starting from the carry's lane 0.
- **Fallback:** if AVX2 is not available, a plain scalar loop is used.

<answer>
```c
#include <immintrin.h>

void prefix_sum_i64(const int64_t *in, int64_t *out, size_t n)
{
    size_t i = 0;
    int64_t s = 0;
#ifdef __AVX2__
    while (i < n && ((uintptr_t)(out + i) & 31)) {
        s += in[i];
        out[i] = s;
        i++;
    }
    if (n - i >= 4) {
        __m256i carry = _mm256_set1_epi64x(s);
        const __m256i zero = _mm256_setzero_si256();
        for (; i + 8 <= n; i += 8) {
            __m256i x = _mm256_loadu_si256((const __m256i *)(in + i));
            __m256i y = _mm256_loadu_si256((const __m256i *)(in + i + 4));
            _mm_prefetch((const char *)(in + i + 64), _MM_HINT_T0);
            x = _mm256_add_epi64(x, _mm256_slli_si256(x, 8));
            y = _mm256_add_epi64(y, _mm256_slli_si256(y, 8));
            __m256i tx = _mm256_permute4x64_epi64(x, 0x55);
            __m256i ty = _mm256_permute4x64_epi64(y, 0x55);
            x = _mm256_add_epi64(x, _mm256_blend_epi32(zero, tx, 0xF0));
            y = _mm256_add_epi64(y, _mm256_blend_epi32(zero, ty, 0xF0));
            __m256i bx = _mm256_permute4x64_epi64(x, 0xFF);
            __m256i by = _mm256_permute4x64_epi64(y, 0xFF);
            __m256i c1 = _mm256_add_epi64(carry, bx);
            _mm256_stream_si256((__m256i *)(out + i), _mm256_add_epi64(x, carry));
            _mm256_stream_si256((__m256i *)(out + i + 4), _mm256_add_epi64(y, c1));
            carry = _mm256_add_epi64(c1, by);
        }
        for (; i + 4 <= n; i += 4) {
            __m256i x = _mm256_loadu_si256((const __m256i *)(in + i));
            x = _mm256_add_epi64(x, _mm256_slli_si256(x, 8));
            __m256i tx = _mm256_permute4x64_epi64(x, 0x55);
            x = _mm256_add_epi64(x, _mm256_blend_epi32(zero, tx, 0xF0));
            __m256i bx = _mm256_permute4x64_epi64(x, 0xFF);
            _mm256_stream_si256((__m256i *)(out + i), _mm256_add_epi64(x, carry));
            carry = _mm256_add_epi64(carry, bx);
        }
        _mm_sfence();
        s = _mm256_extract_epi64(carry, 0);
    }
#endif
    for (; i < n; i++) {
        s += in[i];
        out[i] = s;
    }
}
