#include <stdint.h>
#include <stdlib.h>
#include <math.h>

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    uint64_t r = (uint64_t)sqrtl((long double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;
    uint64_t *lo = (uint64_t *)malloc((r + 2) * sizeof(uint64_t));
    uint64_t *hi = (uint64_t *)malloc((r + 2) * sizeof(uint64_t));
    if (!lo || !hi) { free(lo); free(hi); return 0; }
    lo[0] = 0;
    for (uint64_t i = 1; i <= r; i++) {
        lo[i] = i - 1;
        hi[i] = n / i - 1;
    }
    for (uint64_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue;
        uint64_t pc = lo[p - 1];
        uint64_t p2 = p * p;
        uint64_t lim = n / p2;
        if (lim > r) lim = r;
        for (uint64_t i = 1; i <= lim; i++) {
            uint64_t d = i * p;
            if (d <= r) hi[i] -= hi[d] - pc;
            else hi[i] -= lo[n / d] - pc;
        }
        for (uint64_t i = r; i >= p2; i--) {
            lo[i] -= lo[i / p] - pc;
        }
    }
    uint64_t res = hi[1];
    free(lo);
    free(hi);
    return res;
