#include <immintrin.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256])
{
    uint64_t t[4][256];
    memset(t, 0, sizeof(t));
    size_t i = 0;
#ifdef __AVX2__
    int cur = -1;
    uint64_t run = 0;
    for (; i + 64 <= n; i += 64) {
        const uint8_t *p = data + i;
        __m256i b = _mm256_set1_epi8((char)p[0]);
        __m256i v0 = _mm256_loadu_si256((const __m256i *)p);
        __m256i v1 = _mm256_loadu_si256((const __m256i *)(p + 32));
        __m256i e = _mm256_and_si256(_mm256_cmpeq_epi8(v0, b),
                                     _mm256_cmpeq_epi8(v1, b));
        if (__builtin_expect((uint32_t)_mm256_movemask_epi8(e) == 0xFFFFFFFFu, 1)) {
            if ((int)p[0] == cur) {
                run += 64;
            } else {
                if (cur >= 0) t[0][cur] += run;
                cur = p[0];
                run = 64;
            }
        } else {
            for (int j = 0; j < 64; j += 4) {
                t[0][p[j]]++;
                t[1][p[j + 1]]++;
                t[2][p[j + 2]]++;
                t[3][p[j + 3]]++;
            }
        }
    }
    if (cur >= 0) t[0][cur] += run;
#endif
    for (; i < n; i++) t[0][data[i]]++;
    for (int c = 0; c < 256; c++)
        counts[c] = t[0][c] + t[1][c] + t[2][c] + t[3][c];
}
