#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static int k_cmp_dummy_u32(const void *x, const void *y) {
    uint32_t a = *(const uint32_t *)x, b = *(const uint32_t *)y;
    return (a > b) - (a < b);
}

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n < 64) {
        for (size_t i = 1; i < n; i++) {
            uint32_t v = a[i];
            size_t j = i;
            while (j > 0 && a[j - 1] > v) {
                a[j] = a[j - 1];
                j--;
            }
            a[j] = v;
        }
        return;
    }
    uint32_t *tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!tmp) {
        qsort(a, n, sizeof(uint32_t), k_cmp_dummy_u32);
        return;
    }
    uint32_t h[3][2048];
    memset(h, 0, sizeof(h));
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        h[0][v & 2047]++;
        h[1][(v >> 11) & 2047]++;
        h[2][v >> 22]++;
    }
    uint32_t *src = a, *dst = tmp;
    for (int p = 0; p < 3; p++) {
        int sh = p * 11;
        uint32_t first = (a[0] >> sh) & 2047;
        if (h[p][first] == n) continue;
        uint32_t sum = 0;
        for (int b = 0; b < 2048; b++) {
            uint32_t c = h[p][b];
            h[p][b] = sum;
            sum += c;
        }
        uint32_t *off = h[p];
        for (size_t i = 0; i < n; i++) {
            uint32_t v = src[i];
            dst[off[(v >> sh) & 2047]++] = v;
        }
        uint32_t *t = src; src = dst; dst = t;
    }
    if (src != a) memcpy(a, src, n * sizeof(uint32_t));
    free(tmp);
}
