#define MR 12
#define NR 32
#define VL 16
typedef __m512 VEC;
#define LOADU _mm512_loadu_ps
#define STOREU _mm512_storeu_ps
#define SET1 _mm512_set1_ps
#define FMA _mm512_fmadd_ps
#define ZERO _mm512_setzero_ps
#define HAVE_SIMD 1
#elif defined(__AVX2__) && defined(__FMA__)
#define MR 6
#define NR 16
#define VL 8
typedef __m256 VEC;
#define LOADU _mm256_loadu_ps
#define STOREU _mm256_storeu_ps
#define SET1 _mm256_set1_ps
#define FMA _mm256_fmadd_ps
#define ZERO _mm256_setzero_ps
#define HAVE_SIMD 1
#else
#define HAVE_SIMD 0
#endif

#define KC 192

static void edge_region(const float *A, const float *B, float *C, size_t n,
                        size_t i0, size_t i1, size_t j0, size_t j1)
{
    for (size_t i = i0; i < i1; i++) {
        float *c = C + i * n;
        for (size_t j = j0; j < j1; j++) c[j] = 0.0f;
        for (size_t k = 0; k < n; k++) {
            float a = A[i * n + k];
            const float *b = B + k * n;
            for (size_t j = j0; j < j1; j++) c[j] += a * b[j];
        }
    }
}

#if HAVE_SIMD
static float packbuf[KC * NR] __attribute__((aligned(64)));

static inline void kern(const float *A, const float *Bp, float *C, size_t n,
                        size_t kc, int first)
{
    enum { NV = NR / VL };
    VEC acc[MR][NV];
    if (first) {
        for (int r = 0; r < MR; r++)
            for (int v = 0; v < NV; v++) acc[r][v] = ZERO();
    } else {
        for (int r = 0; r < MR; r++)
            for (int v = 0; v < NV; v++) acc[r][v] = LOADU(C + (size_t)r * n + v * VL);
    }
    for (size_t k = 0; k < kc; k++) {
        VEC b[NV];
        for (int v = 0; v < NV; v++) b[v] = LOADU(Bp + k * NR + v * VL);
#pragma GCC unroll 12
        for (int r = 0; r < MR; r++) {
            VEC a = SET1(A[(size_t)r * n + k]);
#pragma GCC unroll 2
            for (int v = 0; v < NV; v++) acc[r][v] = FMA(a, b[v], acc[r][v]);
        }
    }
    for (int r = 0; r < MR; r++)
        for (int v = 0; v < NV; v++) STOREU(C + (size_t)r * n + v * VL, acc[r][v]);
}
#endif

void matmul_f32(const float *A, const float *B, float *C, size_t n)
{
    if (n == 0) return;
#if HAVE_SIMD
    size_t nm = n / MR * MR;
    size_t nn = n / NR * NR;
    if (nm > 0 && nn > 0) {
        for (size_t k0 = 0; k0 < n; k0 += KC) {
            size_t kc = n - k0 < KC ? n - k0 : KC;
            int first = (k0 == 0);
            for (size_t j = 0; j < nn; j += NR) {
                for (size_t k = 0; k < kc; k++) {
                    const float *src = B + (k0 + k) * n + j;
                    float *dst = packbuf + k * NR;
                    for (int t = 0; t < NR; t++) dst[t] = src[t];
                }
                for (size_t i = 0; i < nm; i += MR) {
                    kern(A + i * n + k0, packbuf, C + i * n + j, n, kc, first);
                }
            }
        }
        if (nn < n) edge_region(A, B, C, n, 0, nm, nn, n);
        if (nm < n) edge_region(A, B, C, n, nm, n, 0, n);
        return;
    }
#endif
    edge_region(A, B, C, n, 0, n, 0, n);
}
