#include <immintrin.h>

#ifdef __AVX512F__
#define VB 64
#define MRR 12
#else
#define VB 32
#define MRR 6
#endif
#define VLN (VB / 4)
#define NRR (2 * VLN)
#define KCB 192
#define NCB 384

typedef float vec __attribute__((vector_size(VB)));
typedef float vecu __attribute__((vector_size(VB), aligned(4)));

static inline __attribute__((always_inline))
void kern(const float *restrict ap, const float *restrict bp, size_t kc, vec acc[MRR][2])
{
    for (size_t k = 0; k < kc; k++) {
        vec b0 = *(const vec *)(bp + k * NRR);
        vec b1 = *(const vec *)(bp + k * NRR + VLN);
#pragma GCC unroll 12
        for (int r = 0; r < MRR; r++) {
            float a = ap[k * MRR + r];
            acc[r][0] += a * b0;
            acc[r][1] += a * b1;
        }
    }
}

void matmul_f32(const float *A, const float *B, float *C, size_t n)
{
    if (n == 0) return;
    memset(C, 0, n * n * sizeof(float));
    float *Bp = (float *)aligned_alloc(64, (size_t)KCB * (NCB + NRR) * sizeof(float));
    if (!Bp) return;
    float *Ap = (float *)aligned_alloc(64, (size_t)KCB * MRR * sizeof(float));
    if (!Ap) { free(Bp); return; }

    for (size_t jc = 0; jc < n; jc += NCB) {
        size_t ncur = n - jc < NCB ? n - jc : NCB;
        size_t npan = (ncur + NRR - 1) / NRR;
        for (size_t pc = 0; pc < n; pc += KCB) {
            size_t kc = n - pc < KCB ? n - pc : KCB;
            /* pack B */
            for (size_t p = 0; p < npan; p++) {
                size_t j0 = p * NRR;
                size_t w = ncur - j0 < NRR ? ncur - j0 : NRR;
                float *dst = Bp + p * kc * NRR;
                for (size_t k = 0; k < kc; k++) {
                    const float *src = B + (pc + k) * n + jc + j0;
                    float *d = dst + k * NRR;
                    size_t t = 0;
                    for (; t < w; t++) d[t] = src[t];
                    for (; t < NRR; t++) d[t] = 0.0f;
                }
            }
            for (size_t i = 0; i < n; i += MRR) {
                size_t mr = n - i < MRR ? n - i : MRR;
                /* pack A */
                for (size_t r = 0; r < MRR; r++) {
                    if (r < mr) {
                        const float *src = A + (i + r) * n + pc;
                        for (size_t k = 0; k < kc; k++) Ap[k * MRR + r] = src[k];
                    } else {
                        for (size_t k = 0; k < kc; k++) Ap[k * MRR + r] = 0.0f;
                    }
                }
                for (size_t p = 0; p < npan; p++) {
                    size_t j0 = p * NRR;
                    size_t w = ncur - j0 < NRR ? ncur - j0 : NRR;
                    vec acc[MRR][2];
                    for (int r = 0; r < MRR; r++) {
                        acc[r][0] = (vec){0};
                        acc[r][1] = (vec){0};
                    }
                    kern(Ap, Bp + p * kc * NRR, kc, acc);
                    float *c = C + i * n + jc + j0;
                    if (mr == MRR && w == NRR) {
#pragma GCC unroll 12
                        for (int r = 0; r < MRR; r++) {
                            vecu *c0 = (vecu *)(c + (size_t)r * n);
                            vecu *c1 = (vecu *)(c + (size_t)r * n + VLN);
                            *c0 = *c0 + acc[r][0];
                            *c1 = *c1 + acc[r][1];
                        }
                    } else {
                        float tmp[MRR][NRR] __attribute__((aligned(64)));
                        for (int r = 0; r < MRR; r++) {
                            *(vecu *)(&tmp[r][0]) = acc[r][0];
                            *(vecu *)(&tmp[r][VLN]) = acc[r][1];
                        }
                        for (size_t r = 0; r < mr; r++)
                            for (size_t t = 0; t < w; t++)
                                c[r * n + t] += tmp[r][t];
                    }
                }
            }
        }
    }
    free(Ap);
    free(Bp);
}
