        c3 += (uint64_t)__builtin_popcountll(a[i + 3]) + (uint64_t)__builtin_popcountll(a[i + 7]);
    }
    total = c0 + c1 + c2 + c3;
#endif
    for (; i < n; i++)
        total += (uint64_t)__builtin_popcountll(a[i]);
