#include <sys/mman.h>

size_t count_distinct_u32(const uint32_t *a, size_t n)
{
    if (n == 0) return 0;
    const size_t bytes = (size_t)1 << 23; /* 2^26 bits */
    int mapped = 1;
    uint64_t *bm = (uint64_t *)mmap(NULL, bytes, PROT_READ | PROT_WRITE,
                                    MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (bm == (uint64_t *)MAP_FAILED) {
        mapped = 0;
        bm = (uint64_t *)calloc(bytes, 1);
        if (!bm) return 0;
    } else {
