    }
    size_t cnt = 0;
    size_t i = 0;
    const size_t D = 32;
    if (n > D) {
        size_t lim = n - D;
        for (; i < lim; i++) {
            __builtin_prefetch(&bm[a[i + D] >> 6], 1, 0);
            uint32_t v = a[i];
            size_t idx = v >> 6;
            unsigned b = v & 63;
            uint64_t w = bm[idx];
            cnt += ((w >> b) & 1) ^ 1;
            bm[idx] = w | (1ULL << b);
