    for (; i < n; i++) {
        uint32_t v = a[i];
        size_t idx = v >> 6;
        unsigned b = v & 63;
        uint64_t w = bm[idx];
        cnt += ((w >> b) & 1) ^ 1;
        bm[idx] = w | (1ULL << b);
    }
    if (mapped) munmap(bm, bytes);
    else free(bm);
    return cnt;
}
