        bm[v1 >> 6] |= 1ULL << (v1 & 63);
        bm[v2 >> 6] |= 1ULL << (v2 & 63);
        bm[v3 >> 6] |= 1ULL << (v3 & 63);
    }
    for (; i < n; i++) {
        uint32_t v = a[i];
        bm[v >> 6] |= 1ULL << (v & 63);
