        c0 += __builtin_popcountll(bm[j]);
        c1 += __builtin_popcountll(bm[j + 1]);
        c2 += __builtin_popcountll(bm[j + 2]);
        c3 += __builtin_popcountll(bm[j + 3]);
    }
