    for (size_t i0 = 0; i0 < R8; i0 += T) {
        size_t i1 = i0 + T < R8 ? i0 + T : R8;
        for (size_t j0 = 0; j0 < C8; j0 += T) {
            size_t j1 = j0 + T < C8 ? j0 + T : C8;
