                    tr8x8(in + i * cols + j, cols, out + j * rows + i, rows);
        }
    }
    /* leftover columns (j >= C8) for rows < R8 */
    if (C8 < cols) {
        for (size_t i = 0; i < rows; i++)
            for (size_t j = C8; j < cols; j++)
                out[j * rows + i] = in[i * cols + j];
    }
    /* leftover rows (i >= R8) for columns < C8 */
    if (R8 < rows) {
        for (size_t i = R8; i < rows; i++)
            for (size_t j = 0; j < C8; j++)
                out[j * rows + i] = in[i * cols + j];
    }
}
