size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;
    size_t W = (n + 63) >> 6;
    int map[256];
    for (int i = 0; i < 256; i++) map[i] = -1;
    int k = 0;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        if (map[c] < 0) map[c] = k++;
    }
    /* rows 0..k-1 for chars, row k zeros */
    uint64_t *buf = (uint64_t *)calloc((size_t)(k + 1) * W + 2 * W, sizeof(uint64_t));
    if (!buf) return (size_t)-1;
    uint64_t *Peq = buf;
    uint64_t *Pv = buf + (size_t)(k + 1) * W;
    uint64_t *Mv = Pv + W;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        Peq[(size_t)map[c] * W + (i >> 6)] |= (uint64_t)1 << (i & 63);
    }
    for (size_t b = 0; b < W; b++) { Pv[b] = ~(uint64_t)0; Mv[b] = 0; }
    for (int i = 0; i < 256; i++) if (map[i] < 0) map[i] = k;

    uint64_t lastbit = (uint64_t)1 << ((n - 1) & 63);
    long score = (long)n;
    for (size_t j = 0; j < m; j++) {
        const uint64_t *row = Peq + (size_t)map[(unsigned char)t[j]] * W;
        uint64_t hp = 1, hn = 0;
        uint64_t lPh = 0, lMh = 0;
        for (size_t b = 0; b < W; b++) {
            uint64_t Eq = row[b];
            uint64_t Pvb = Pv[b];
            uint64_t Mvb = Mv[b];
            uint64_t Xv = Eq | Mvb;
            Eq |= hn;
            uint64_t Xh = (((Eq & Pvb) + Pvb) ^ Pvb) | Eq;
            uint64_t Ph = Mvb | ~(Xh | Pvb);
            uint64_t Mh = Pvb & Xh;
            uint64_t ohp = Ph >> 63;
            uint64_t ohn = Mh >> 63;
            lPh = Ph; lMh = Mh;
            Ph = (Ph << 1) | hp;
            Mh = (Mh << 1) | hn;
            Pv[b] = Mh | ~(Xv | Ph);
            Mv[b] = Ph & Xv;
            hp = ohp;
            hn = ohn;
        }
        if (lPh & lastbit) score++;
        else if (lMh & lastbit) score--;
    }
    free(buf);
    return (size_t)score;
}
