#include <stdint.h>

size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;
    size_t W = (n + 63) >> 6;
    int idx[256];
    memset(idx, 0, sizeof(idx));
    int distinct = 0;
    const unsigned char *us = (const unsigned char *)s;
    const unsigned char *ut = (const unsigned char *)t;
    for (size_t i = 0; i < n; i++) {
        if (!idx[us[i]]) idx[us[i]] = ++distinct;
    }
    uint64_t *peq = (uint64_t *)calloc((size_t)(distinct + 1) * W, sizeof(uint64_t));
    uint64_t *Pv = (uint64_t *)malloc(W * sizeof(uint64_t));
    uint64_t *Mv = (uint64_t *)malloc(W * sizeof(uint64_t));
    if (!peq || !Pv || !Mv) {
        free(peq); free(Pv); free(Mv);
        return (size_t)-1;
    }
    for (size_t i = 0; i < n; i++) {
        peq[(size_t)idx[us[i]] * W + (i >> 6)] |= (uint64_t)1 << (i & 63);
    }
    for (size_t b = 0; b < W; b++) { Pv[b] = ~(uint64_t)0; Mv[b] = 0; }

    size_t score = n;
    const uint64_t lastmask = (uint64_t)1 << ((n - 1) & 63);
    size_t last = W - 1;

    for (size_t j = 0; j < m; j++) {
        const uint64_t *row = peq + (size_t)idx[ut[j]] * W;
        uint64_t hp = 1, hm = 0;
        for (size_t b = 0; b < last; b++) {
            uint64_t pv = Pv[b], mv = Mv[b];
            uint64_t eq = row[b];
            uint64_t xv = eq | mv;
            eq |= hm;
            uint64_t xh = (((eq & pv) + pv) ^ pv) | eq;
            uint64_t ph = mv | ~(xh | pv);
            uint64_t mh = pv & xh;
            uint64_t nhp = ph >> 63, nhm = mh >> 63;
            ph = (ph << 1) | hp;
            mh = (mh << 1) | hm;
            Pv[b] = mh | ~(xv | ph);
            Mv[b] = ph & xv;
            hp = nhp; hm = nhm;
        }
        {
            size_t b = last;
            uint64_t pv = Pv[b], mv = Mv[b];
            uint64_t eq = row[b];
            uint64_t xv = eq | mv;
            eq |= hm;
            uint64_t xh = (((eq & pv) + pv) ^ pv) | eq;
            uint64_t ph = mv | ~(xh | pv);
            uint64_t mh = pv & xh;
            score += ((ph & lastmask) != 0);
            score -= ((mh & lastmask) != 0);
            ph = (ph << 1) | hp;
            mh = (mh << 1) | hm;
            Pv[b] = mh | ~(xv | ph);
            Mv[b] = ph & xv;
        }
    }
    free(peq); free(Pv); free(Mv);
    return score;
}
