```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static inline void lev_block(uint64_t *pvp, uint64_t *mvp, uint64_t eq,
                             uint64_t *ph_in, uint64_t *mh_in, unsigned sh,
                             long *score, int last)
{
    uint64_t Pv = *pvp, Mv = *mvp;
    uint64_t Xv = eq | Mv;
    eq |= *mh_in;
    uint64_t Xh = (((eq & Pv) + Pv) ^ Pv) | eq;
    uint64_t Ph = Mv | ~(Xh | Pv);
    uint64_t Mh = Pv & Xh;
    uint64_t pout = (Ph >> sh) & 1;
    uint64_t mout = (Mh >> sh) & 1;
    Ph = (Ph << 1) | *ph_in;
    Mh = (Mh << 1) | *mh_in;
    *pvp = Mh | ~(Xv | Ph);
    *mvp = Ph & Xv;
    *ph_in = pout;
    *mh_in = mout;
    if (last) *score += (long)pout - (long)mout;
}

size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;
    size_t B = (n + 63) / 64;
    int idx[256];
    for (int i = 0; i < 256; i++) idx[i] = -1;
    int cnt = 0;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        if (idx[c] < 0) idx[c] = cnt++;
    }
    /* rows 0..cnt-1 for chars, row cnt is zero row */
    size_t rows = (size_t)cnt + 1;
    uint64_t *buf = (uint64_t *)calloc(rows * B + 2 * B, sizeof(uint64_t));
    if (!buf) return 0;
    uint64_t *peq = buf;
    uint64_t *Pv = buf + rows * B;
    uint64_t *Mv = Pv + B;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        peq[(size_t)idx[c] * B + (i >> 6)] |= 1ULL << (i & 63);
    }
    for (size_t b = 0; b < B; b++) { Pv[b] = ~0ULL; Mv[b] = 0; }
    long score = (long)n;
    unsigned lastsh = (unsigned)((n - 1) & 63);
    for (size_t j = 0; j < m; j++) {
        int id = idx[(unsigned char)t[j]];
        if (id < 0) id = cnt;
        const uint64_t *row = peq + (size_t)id * B;
        uint64_t ph = 1, mh = 0;
        for (size_t b = 0; b + 1 < B; b++)
            lev_block(&Pv[b], &Mv[b], row[b], &ph, &mh, 63, &score, 0);
        lev_block(&Pv[B - 1], &Mv[B - 1], row[B - 1], &ph, &mh, lastsh, &score, 1);
    }
    free(buf);
    return (size_t)score;
}
