                    zy[k] = _mm256_add_pd(_mm256_mul_pd(t, two), cy);
                    zx[k] = _mm256_add_pd(_mm256_sub_pd(zx2[k], zy2[k]), cx[k]);
                    zx2[k] = _mm256_mul_pd(zx[k], zx[k]);
                    zy2[k] = _mm256_mul_pd(zy[k], zy[k]);
                    __m256d r2 = _mm256_add_pd(zx2[k], zy2[k]);
                    act[k] = _mm256_and_pd(act[k], _mm256_cmp_pd(r2, four, _CMP_LE_OQ));
                    anyv = _mm256_or_pd(anyv, act[k]);
                }
                if (_mm256_movemask_pd(anyv) == 0) break;
            }
            for (int k = 0; k < 4; k++)
                rowcnt += __builtin_popcount(_mm256_movemask_pd(act[k]));
        }
        total += rowcnt * weight;
    }
#else
    for (int py = 0; py < rows; py++) {
        double cy = -1.5 + 3.0 * (py + 0.5) / h;
        uint64_t weight = (h & 1) && py == h / 2 ? 1 : 2;
        uint64_t rowcnt = 0;
        for (int px = 0; px < w; px++) {
            double cx = -2.0 + 3.0 * (px + 0.5) / w;
            double xm = cx - 0.25, q = xm * xm + cy * cy;
            if (q * (q + xm) <= 0.25 * cy * cy ||
                (cx + 1) * (cx + 1) + cy * cy <= 0.0625) { rowcnt++; continue; }
            double x = 0, y = 0;
            int esc = 0;
            for (int i = 0; i < max_iter; i++) {
                double nx = x * x - y * y + cx;
                y = 2 * x * y + cy;
                x = nx;
                if (x * x + y * y > 4.0) { esc = 1; break; }
            }
            if (!esc) rowcnt++;
        }
        total += rowcnt * weight;
    }
#endif
    return total;
